    star_mass_sun: float,
    gamma_ms: float = 0.0,
    *,
    t_ref_days: float | None = None,
) -> np.ndarray:
    """Forward-model a non-interacting multi-planet RV signal.

    `l_rad` is mean longitude at `t_ref_days` (default: `times_days[0]`).
